head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > visibleRowNum]<br/>Body 영역에 표시할 Row 의 갯수를 설정합니다.",
    "validation" : [
        "'' (default) 설정 시 디자인 시 설정한 GridView 의 높이에 맞춰 데이터를 표시합니다. GridView 에 데이터가 모두 표시되지 않으면 스크롤이 생성됩니다.",
        "Number 설정 시 GridView 의 Body 영역에 한번에 표시할 Row 의 갯수를 숫자로 설정합니다. GridView 의 높이가 설정값에 맞게 변경되며 설정값보다 데이터 수가 많을 경우 스크롤이 생성됩니다. 디자인 시 설정한 GridView 의 높이보다 작아지지 않습니다. SubTotal Row 는 설정값의 Row 갯수에 포함되지 않습니다.",
        "'all' 설정 시 SubTotal Row 를 포함하여 모든 데이터 Row 가 표시되게 GridView 의 높이가 변경됩니다. 디자인 시 설정한 GridView 의 높이보다 작아지지 않습니다.",
        "visibleRowNum 속성을 숫자로 설정하면 initFixedHeightByRowNum 속성은 -1 로 설정됩니다. initFixedHeightByRowNum 속성은 visibleRowNum 속성이 ''(default) 일 때만 적용됩니다.",
        "setGridHeight() 메소드 실행 시 visibleRowNum 속성은 무시되고 GridView 의 높이가 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성 (10 행 — visibleRowNum 값에 따른 높이 차이가 보이도록 충분히 많은 데이터 확보)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // 조건 설정 (visibleRowNum 미설정 시 '' → createCList 가 빈 문자열 속성을 제외하므로 Property 미설정 상태로 생성)
    let properties = {
        visibleRowNum: con_visibleRowNum.getValue(),
        initFixedHeightByRowNum: con_initFixedHeightByRowNum.getValue(),
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 디자인 높이를 작게(약 3행) 설정 → visibleRowNum 을 숫자로 설정해도 그리드가 해당 행 수에 정확히 맞춰져 하단 빈 영역이 생기지 않음
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:171px;">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);

    scwin.btn_visibleRowNum_onclick();
}



// visibleRowNum 확인 — getVisibleRowNum(), 실제 렌더 높이, 스크롤 유무 출력
scwin.btn_visibleRowNum_onclick = function (e) {
    let elem = target1.render;
    let height = elem ? elem.offsetHeight : 'N/A';

    // Body 세로 스크롤 영역 (.w2grid_scrollY) — 스크롤 유무 판단
    let scrollArea = elem ? elem.querySelector('.w2grid_scrollY') : null;
    let hasScroll = scrollArea ? (scrollArea.scrollHeight > scrollArea.clientHeight) : 'N/A';

    wf_body_bottom.getObj("scwin").setReturnValue("getVisibleRowNum() (화면에 보이는 행 수) : " + target1.getVisibleRowNum());
    wf_body_bottom.getObj("scwin").setReturnValue("GridView 렌더 높이(offsetHeight) : " + height);
    wf_body_bottom.getObj("scwin").setReturnValue("세로 스크롤 생성 여부 : " + hasScroll);
    wf_body_bottom.getObj("scwin").setReturnValue("설정한 initFixedHeightByRowNum(con) : '" + con_initFixedHeightByRowNum.getValue() + "' / 적용된 options.initFixedHeightByRowNum : " + target1.options.initFixedHeightByRowNum);
}



// setGridHeight() — visibleRowNum 무시되고 GridView 높이가 변경됨 (@spec)
scwin.btn_setGridHeight_onclick = function (e) {
    target1.setGridHeight(150);

    let elem = target1.render;
    let height = elem ? elem.offsetHeight : 'N/A';

    wf_body_bottom.getObj("scwin").setReturnValue("setGridHeight(150) 실행 후 렌더 높이(offsetHeight) : " + height);
    wf_body_bottom.getObj("scwin").setReturnValue("setGridHeight 실행 후 getVisibleRowNum() : " + target1.getVisibleRowNum());
}
